# owner: platform
"""Seating charts: students sorted by last name and split into rows."""

import rosterkit.errors


def _check(students, seats_per_row):
    if seats_per_row <= 0:
        raise rosterkit.errors.ProjectError("seats per row must be positive")
    if not students:
        raise rosterkit.errors.ProjectError("no students to seat")


def _sort_key(student):
    return (student.last_name.lower(), student.first_name.lower())


def _chunk(items, size):
    rows = []
    for start in range(0, len(items), size):
        rows.append(items[start:start + size])
    return rows


def _format_row(number, row):
    names = []
    for student in row:
        names.append(student.display_name)
    return f"Row {number}: " + " | ".join(names)


# ---
def seat_rows(students, seats_per_row):
    """Return one line of text per row, students ordered by last name."""
    _check(students, seats_per_row)
    ordered = sorted(students, key=_sort_key)
    lines = []
    for index, row in enumerate(_chunk(ordered, seats_per_row), 1):
        lines.append(_format_row(index, row))
    return lines


# end of file
